async function getConfirmation(uid) {
	const code = await db.get(`confirm:byUid:${uid}`);
	if (!code) {
		return null;
	}
	const confirmation = await db.getObject(`confirm:${code}`);
	if (!confirmation || parseInt(confirmation.uid, 10) !== parseInt(uid, 10) || !confirmation.email) {
		return null;
	}
	return { code, confirmation };
